head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.gDepCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gMktTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
        await scwin.setCode();
        scwin.listSync();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05238.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.setBzProcsNo(row);
        vBzProcsNo = scwin.clickBzProcsNo;
        await scwin.fileAdd(vBzProcsNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05238.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            scwin.listSync();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05238.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05238.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '') {
            cmb_TeamList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05238.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05238.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue("20030501");
    edt_EDate.setValue("20080825");
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let url = "/listingCommon.do?SCREN_ID=" + "ULDSTF05238.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=KLSLIST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.select.kosdaq.klslist" + "&{P}param01=" + edt_SDate.getValue() + // 일자
        "&{P}param02=" + edt_EDate.getValue() + // 일자
        "&{P}param03=" + txb_ISUR_CD.getValue() + // 회사코드
        "&{P}param04=" + txb_ISUR_CD.getValue() + // 회사코드
        "&{P}param05=" + cmb_TeamList.getValue() + // 담당팀
        "&{P}param06=" + cmb_TeamList.getValue() + // 담당팀
        "&{P}param07=" + cmb_EmpList.getValue() + // 담당자
        "&{P}param08=" + cmb_EmpList.getValue() + // 담당자
        "&{P}param09=" + rdo_APPROV_YN.getValue() + // 상태
        "&{P}param10=" + rdo_APPROV_YN.getValue(); // 상태

    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF05238.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "KLS변경상장 첨부파일 조회", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name fileAdd
 * @description 2009.02.10 첨부파일추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileAdd = async function() {
    // alert("파일첨부");
    let url = "/lstproc/ULDSTF05003_FILELIST.gfm?BZ_PROCS_NO=" + vBzProcsNo;
    await $c.frame.CreateDialogFrame("DLG_PREEXAM", url, "첨부파일목록", 100, 100, 710, 300, "window");
};
